/* ==========================================================================
   Jarvis - settings/setup UI translations

   Generated file. One global object, loaded with a plain <script> tag
   before app.js, so it works straight from the filesystem with no server
   and no fetch(). Keys are the ENGLISH SOURCE STRINGS, so a missing
   translation always falls back to readable English rather than a raw key.

   Languages: en, es, fr, de, pt-BR, it, nl, pl, ru, zh-CN, ja, ko, hi, ar, tr
   ========================================================================== */
