    ", and are pruned after the retention window set in Privacy. Nothing here is uploaded.": ", y se eliminan tras el período de retención definido en Privacidad. Nada de esto se sube.",
    "<b>These tests are billable.</b> Jarvis sends a short sample to the speech service and you are charged for it.": "<b>Estas pruebas son de pago.</b> Jarvis envía una muestra corta al servicio de voz y se te cobra por ella.",
    "A more capable you.": "Un tú con más capacidades.",
    "A small local model listens for your wake phrase so you can start talking without touching the keyboard. Nothing is uploaded while it listens.": "Un pequeño modelo local escucha tu frase de activación para que empieces a hablar sin tocar el teclado. Mientras escucha no se sube nada.",
    "A smoother, faster way to work — with your voice.": "Una forma de trabajar más ágil y fluida — con tu voz.",
