    "Integrations": "Integraciones",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis cuenta lo que gasta y se detiene al alcanzar un tope. Define un tope bajo la primera semana y súbelo cuando conozcas tus hábitos.",
