    ", and are pruned after the retention window set in Privacy. Nothing here is uploaded.": ", et sont supprimées après la fenêtre de conservation définie dans Confidentialité. Rien de tout ceci n'est envoyé.",
    "<b>These tests are billable.</b> Jarvis sends a short sample to the speech service and you are charged for it.": "<b>Ces tests sont payants.</b> Jarvis envoie un court extrait au service vocal et cela vous est facturé.",
    "A more capable you.": "Un vous plus performant.",
