    "Integrations": "Intégrations",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis compte ce qu'il dépense et s'arrête lorsqu'un plafond est atteint. Fixez un plafond bas la première semaine, puis augmentez-le une fois vos habitudes connues.",
