    "Phrases: {list}": "Phrases : {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Choisissez le microphone dans lequel vous parlez réellement, puis observez le vumètre pendant que vous parlez. Une bonne entrée culmine à environ deux tiers de la barre sans saturation.",
    "Polish": "Soigné",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "Appuyez sur un raccourci, parlez naturellement, et vos mots arrivent dans l'application qui a le focus. Cette configuration rapide règle votre audio, vos raccourcis et vos préférences. Vous pourrez tout modifier plus tard dans Réglages.",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "Appuyez sur la combinaison de touches ou le bouton de souris pour « {name} ». Appuyez sur Échap dans cette boîte pour arrêter d'attendre ici.",
