    "The assistant can only read and write inside these folders.": "L'assistant ne peut lire et écrire que dans ces dossiers.",
    "The assistant can only touch what you approve here. Nothing is approved by default, so it will ask before reaching outside a folder you have added.": "L'assistant ne peut toucher qu'à ce que vous approuvez ici. Rien n'est approuvé par défaut, il demandera donc avant de sortir d'un dossier que vous avez ajouté.",
