    "Clearing history removes stored transcripts from this machine. Stored facts above are kept until you forget them individually.": "Verlauf löschen entfernt gespeicherte Transkripte von diesem Gerät. Die gemerkten Fakten oben bleiben, bis du sie einzeln vergisst.",
    "Clears stored transcripts and remembered facts from this machine. Settings and your API key are kept.": "Löscht gespeicherte Transkripte und gemerkte Fakten von diesem Gerät. Einstellungen und dein API-Schlüssel bleiben erhalten.",
