    "If you have Codex or Claude Code installed, Jarvis can hand long jobs to them. Both are optional — dictation works without either.": "Wenn Codex oder Claude Code installiert ist, kann Jarvis lange Aufgaben an sie übergeben. Beide sind optional — Diktieren funktioniert auch ohne.",
