    "Integrations": "Integrationen",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis zählt, was er ausgibt, und stoppt bei Erreichen einer Obergrenze. Setze in der ersten Woche ein niedriges Limit und erhöhe es, wenn du deine Gewohnheiten kennst.",
