    "Jarvis is working": "Jarvis arbeitet",
    "Jarvis lives in the tray. Starting at login means your shortcuts work from the moment you sign in.": "Jarvis lebt im Infobereich. Beim Start mit Windows funktionieren deine Tastenkürzel ab der Anmeldung.",
    "Jarvis needs your OK": "Jarvis braucht dein OK",
    "Jarvis talks to the speech service with your key. It is stored in Windows Credential Manager and never echoed back into this window.": "Jarvis spricht über deinen Schlüssel mit dem Sprachdienst. Er wird im Windows-Anmeldeinformations-Manager gespeichert und nie wieder in diesem Fenster angezeigt.",
