    "Nothing here yet.": "Hier ist noch nichts.",
    "Nothing is sent anywhere until you finish and start dictating, except the connection tests you choose to run.": "Es wird nichts irgendwohin gesendet, bis du fertig bist und zu diktieren beginnst — außer den Verbindungstests, die du selbst ausführst.",
    "Nothing matches “{query}”.": "Nichts passt zu „{query}“.",
    "Nothing remembered yet. Things you ask the assistant to remember will show up here.": "Noch nichts gemerkt. Was du den Assistenten bittest zu merken, erscheint hier.",
    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "Standardmäßig aus. Sendet nur Absturzberichte und Funktionszähler — niemals Transkripte oder Audio.",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "Standardmäßig aus. Wenn aktiv, wird das Audio zu jedem Transkript auf die Festplatte geschrieben, damit du es erneut abspielen kannst.",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "Optional — nichts läuft, bis du es drückst.",
    "Optional accuracy comparison": "Optionaler Genauigkeitsvergleich",
    "Pages the assistant may fetch or summarise. Anything else is refused.": "Seiten, die der Assistent abrufen oder zusammenfassen darf. Alles andere wird abgelehnt.",
    "Phrases: {list}": "Phrasen: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Wähle das Mikrofon, in das du tatsächlich sprichst, und beobachte beim Sprechen den Pegelanzeiger. Ein gutes Eingangssignal erreicht etwa zwei Drittel des Balkens ohne Übersteuern.",
    "Polish": "Feinschliff",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "Drücke ein Tastenkürzel, sprich natürlich, und deine Worte landen in der fokussierten App. Diese kurze Einrichtung stimmt Audio, Tastenkürzel und Einstellungen ab. Alles lässt sich später in den Einstellungen ändern.",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "Drücke die Tastenkombination oder Maustaste für „{name}“. Drücke in diesem Dialog Escape, um hier nicht weiter zu warten.",
    "Press the key combination or mouse button you want to use.": "Drücke die Tastenkombination oder Maustaste, die du verwenden möchtest.",
