    "Integrations": "Integrações",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "O Jarvis conta o que gasta e para quando atinge um limite. Defina um limite baixo na primeira semana e aumente quando conhecer seus hábitos.",
