    "Phrases: {list}": "Frases: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Escolha o microfone em que você realmente fala e observe o medidor de nível enquanto fala. Uma boa entrada chega a cerca de dois terços da barra sem distorção.",
