    "If you have Codex or Claude Code installed, Jarvis can hand long jobs to them. Both are optional — dictation works without either.": "Se hai installato Codex o Claude Code, Jarvis può affidare loro lavori lunghi. Sono entrambi opzionali — la dettatura funziona senza.",
