    "Integrations": "Integrazioni",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis conta quanto spende e si ferma quando raggiunge un tetto. Imposta un tetto basso la prima settimana e alzalo quando conosci le tue abitudini.",
