    "Jarvis lives in the tray. Starting at login means your shortcuts work from the moment you sign in.": "Jarvis vive nell'area di notifica. Avviarlo con Windows fa funzionare le scorciatoie dall'accesso.",
    "Jarvis needs your OK": "Jarvis attende il tuo OK",
    "Jarvis talks to the speech service with your key. It is stored in Windows Credential Manager and never echoed back into this window.": "Jarvis parla con il servizio vocale usando la tua chiave. È archiviata in Gestione credenziali di Windows e non viene mai più mostrata in questa finestra.",
