    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "Disattivato per impostazione predefinita. Invia solo report di arresti anomali e contatori di funzioni — mai trascrizioni o audio.",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "Disattivato per impostazione predefinita. Se attivo, l'audio di ogni trascrizione viene scritto su disco per poterlo riascoltare.",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "Opzionale — non viene eseguito nulla finché non premi.",
    "Optional accuracy comparison": "Confronto di precisione opzionale",
    "Pages the assistant may fetch or summarise. Anything else is refused.": "Pagine che l'assistente può recuperare o riassumere. Qualsiasi altra viene rifiutata.",
    "Phrases: {list}": "Frasi: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Scegli il microfono in cui parli davvero, poi osserva il misuratore di livello mentre parli. Un buon ingresso arriva a circa due terzi della barra senza saturare.",
    "Polish": "Rifinito",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "Premi una scorciatoia, parla naturalmente e le tue parole finiscono nell'app che ha il focus. Questa configurazione rapida sistema audio, scorciatoie e preferenze. Puoi cambiare tutto in seguito in Impostazioni.",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "Premi la combinazione di tasti o il pulsante del mouse per «{name}». Premi Esc in questa finestra per smettere di attendere.",
