    "Phrases: {list}": "Zinnen: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Kies de microfoon waarin je echt praat en kijk naar de niveaumeter terwijl je praat. Een goede invoer piekt rond twee derde van de balk zonder te clippen.",
    "Polish": "Verfijnd",
