    "Integrations": "Integracje",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis liczy, ile wydaje, i zatrzymuje się po osiągnięciu limitu. Ustaw niski limit na pierwszy tydzień i zwiększ go, gdy poznasz swoje nawyki.",
