    "Jarvis talks to the speech service with your key. It is stored in Windows Credential Manager and never echoed back into this window.": "Jarvis rozmawia z usługą mowy za pomocą twojego klucza. Jest przechowywany w Menedżerze poświadczeń Windows i nigdy nie jest ponownie pokazywany w tym oknie.",
