    "Nothing here yet.": "Jeszcze nic tu nie ma.",
    "Nothing is sent anywhere until you finish and start dictating, except the connection tests you choose to run.": "Nic nie jest nigdzie wysyłane, dopóki nie skończysz i nie zaczniesz dyktować — poza testami połączenia, które sam uruchomisz.",
    "Nothing matches “{query}”.": "Nic nie pasuje do „{query}”.",
    "Nothing remembered yet. Things you ask the assistant to remember will show up here.": "Jeszcze nic nie zapamiętano. To, o co poprosisz asystenta, pojawi się tutaj.",
    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "Domyślnie wyłączone. Wysyła tylko raporty awarii i liczniki funkcji — nigdy transkrypcji ani dźwięku.",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "Domyślnie wyłączone. Gdy włączone, dźwięk każdej transkrypcji jest zapisywany na dysku, aby można było go odtworzyć.",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "Opcjonalne — nic się nie uruchamia, dopóki nie naciśniesz.",
    "Optional accuracy comparison": "Opcjonalne porównanie dokładności",
    "Pages the assistant may fetch or summarise. Anything else is refused.": "Strony, które asystent może pobrać lub streścić. Każda inna jest odrzucana.",
    "Phrases: {list}": "Frazy: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Wybierz mikrofon, do którego naprawdę mówisz, i obserwuj miernik poziomu, gdy mówisz. Dobry sygnał osiąga około dwóch trzecich paska bez przesterowania.",
    "Polish": "Dopracowany",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "Naciśnij skrót, mów naturalnie, a twoje słowa trafią do aktywnej aplikacji. Ta szybka konfiguracja ustawia dźwięk, skróty i preferencje. Wszystko możesz zmienić później w Ustawieniach.",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "Naciśnij kombinację klawiszy lub przycisk myszy dla „{name}”. Naciśnij Escape w tym oknie, aby przestać tu czekać.",
    "Press the key combination or mouse button you want to use.": "Naciśnij kombinację klawiszy lub przycisk myszy, którego chcesz użyć.",
    "Privacy": "Prywatność",
    "Private and secure.": "Prywatnie i bezpiecznie.",
    "Punctuation and fillers": "Interpunkcja i słowa wypełniające",
    "Quit Jarvis": "Zamknij Jarvisa",
    "Quit Jarvis? The tray icon and wake listener will stop.": "Zamknąć Jarvisa? Ikona w zasobniku i nasłuch słowa aktywującego zostaną zatrzymane.",
