    "Re-running setup walks through the wizard again without clearing your settings. Quitting closes the tray app and stops the wake listener.": "Ponowne uruchomienie konfiguracji przechodzi przez kreatora bez czyszczenia ustawień. Zamknięcie zamyka aplikację i zatrzymuje nasłuch słowa aktywującego.",
