    "If you have Codex or Claude Code installed, Jarvis can hand long jobs to them. Both are optional — dictation works without either.": "Если у вас установлены Codex или Claude Code, Jarvis может передавать им длинные задачи. Оба необязательны — диктовка работает и без них.",
