    "Installed, not signed in": "Установлено, нет входа",
    "Instantly stops dictation, audio capture and running tools.": "Мгновенно останавливает диктовку, запись звука и работающие инструменты.",
    "Integrations": "Интеграции",
    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis считает, сколько тратит, и останавливается при достижении лимита. Установите низкий лимит на первую неделю и поднимите его, когда узнаете свои привычки.",
