    "Jarvis is working": "Jarvis работает",
    "Jarvis lives in the tray. Starting at login means your shortcuts work from the moment you sign in.": "Jarvis живёт в трее. Запуск при входе делает сочетания клавиш доступными с момента входа.",
    "Jarvis needs your OK": "Jarvis ждёт вашего согласия",
    "Jarvis talks to the speech service with your key. It is stored in Windows Credential Manager and never echoed back into this window.": "Jarvis общается с речевым сервисом по вашему ключу. Он хранится в Диспетчере учётных данных Windows и больше никогда не показывается в этом окне.",
    "Keep raw audio": "Сохранять исходное аудио",
