    "Nothing here yet.": "Здесь пока ничего нет.",
    "Nothing is sent anywhere until you finish and start dictating, except the connection tests you choose to run.": "Ничего никуда не отправляется, пока вы не завершите и не начнёте диктовать, кроме тестов подключения, которые вы решите запустить.",
    "Nothing matches “{query}”.": "Ничего не соответствует «{query}».",
    "Nothing remembered yet. Things you ask the assistant to remember will show up here.": "Пока ничего не запомнено. То, что вы попросите ассистента запомнить, появится здесь.",
    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "По умолчанию выключено. Отправляет только отчёты о сбоях и счётчики функций — никогда расшифровки или аудио.",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "По умолчанию выключено. Если включено, звук каждой расшифровки пишется на диск, чтобы можно было его переслушать.",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "Необязательно — ничего не запускается, пока вы не нажмёте.",
    "Optional accuracy comparison": "Необязательное сравнение точности",
    "Pages the assistant may fetch or summarise. Anything else is refused.": "Страницы, которые ассистент может загрузить или пересказать. Любые другие отклоняются.",
    "Phrases: {list}": "Фразы: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "Выберите микрофон, в который вы действительно говорите, и следите за индикатором уровня во время речи. Хороший сигнал достигает примерно двух третей шкалы без перегрузки.",
    "Polish": "Отточенный",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "Нажмите сочетание клавиш, говорите естественно, и ваши слова попадут в активное приложение. Эта быстрая настройка правильно выставит звук, сочетания клавиш и предпочтения. Всё это можно изменить позже в «Настройках».",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "Нажмите сочетание клавиш или кнопку мыши для «{name}». Нажмите Esc в этом окне, чтобы больше не ждать здесь.",
    "Press the key combination or mouse button you want to use.": "Нажмите сочетание клавиш или кнопку мыши, которые хотите использовать.",
