    "Runs the same audio through the live and economy paths and shows how the transcripts differ, plus the real cost of each. It uses your microphone and is billable.": "Прогоняет одно и то же аудио по пути «вживую» и экономному и показывает, чем отличаются расшифровки, а также реальную стоимость каждого. Использует ваш микрофон и является платным.",
