    "The app rejected that setting change.": "Приложение отклонило это изменение настройки.",
    "The app starts minimised, with the wake listener off until it has finished loading.": "Приложение запускается свёрнутым, с выключенным прослушиванием фразы активации до окончания загрузки.",
    "The assistant can only read and write inside these folders.": "Ассистент может читать и писать только внутри этих папок.",
    "The assistant can only touch what you approve here. Nothing is approved by default, so it will ask before reaching outside a folder you have added.": "Ассистент трогает только то, что вы здесь одобрите. По умолчанию ничего не одобрено, поэтому он спросит, прежде чем выйти за пределы добавленной вами папки.",
    "The key is sent straight to the app and stored in Windows Credential Manager. It is never displayed again — only a short fingerprint is kept for confirmation.": "Ключ отправляется прямо в приложение и хранится в Диспетчере учётных данных Windows. Он больше никогда не показывается — для подтверждения остаётся лишь короткий отпечаток.",
