    "Theme": "Тема",
    "Theme set to {value}": "Тема задана как {value}",
    "These wake the app from anywhere in Windows. The defaults suit most people — change anything you like, and keep one hand free for the emergency stop.": "Они будят приложение из любого места Windows. Значения по умолчанию подходят большинству — меняйте что угодно и держите одну руку свободной для аварийной остановки.",
