    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "默认关闭。只发送崩溃报告和功能计数 —— 绝不发送转录或音频。",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "默认关闭。开启后，每段转录的音频会写入磁盘，以便重放。",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
