    "Pages the assistant may fetch or summarise. Anything else is refused.": "助手可以抓取或总结的页面。其他一律拒绝。",
    "Phrases: {list}": "短语：{list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "选择你实际使用的麦克风，然后对着它说话并观察电平表。良好的输入约为条形的三分之二且不削波。",
    "Polish": "精修",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "按下快捷键，自然说话，你的话就会落入当前聚焦的应用。这次快速设置会把音频、快捷键和偏好调好。以后可以随时在“设置”中更改。",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "为“{name}”按下按键组合或鼠标按钮。在此对话框中按 Escape 即可停止等待。",
