    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "既定ではオフ。クラッシュレポートと機能カウンターのみを送信し、文字起こしや音声は決して送信しません。",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "既定ではオフ。オンにすると、各文字起こしの音声がディスクに書き込まれ、再生し直せます。",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "任意 —— 押すまで何も実行されません。",
