    "Phrases: {list}": "フレーズ：{list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "実際に話すマイクを選び、話しながらレベルメーターを見てください。良い入力はバーの 3 分の 2 ほどで、クリップしません。",
    "Polish": "研磨",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "ショートカットを押して自然に話すと、フォーカス中のアプリに言葉が入ります。この簡単なセットアップでオーディオ、ショートカット、好みを整えます。後で「設定」からいつでも変更できます。",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "「{name}」を使うキーの組み合わせかマウスボタンを押してください。このダイアログで Escape を押すと待機をやめます。",
