    "Clearing history removes stored transcripts from this machine. Stored facts above are kept until you forget them individually.": "기록을 지우면 이 컴퓨터에서 저장된 받아쓰기가 삭제됩니다. 위의 저장된 사실은 하나씩 잊을 때까지 유지됩니다.",
    "Clears stored transcripts and remembered facts from this machine. Settings and your API key are kept.": "이 컴퓨터에서 저장된 받아쓰기와 기억한 사실을 지웁니다. 설정과 API 키는 유지됩니다.",
    "Click Set and then press the key combination or mouse button you want.": "“설정”을 클릭한 뒤 원하는 키 조합이나 마우스 버튼을 누르세요.",
