    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "“{name}”에 사용할 키 조합이나 마우스 버튼을 누르세요. 이 대화 상자에서 Escape 를 누르면 대기를 멈춥니다.",
