    "Clear all stored transcripts? This cannot be undone.": "सभी सहेजे गए ट्रांसक्रिप्ट हटाएँ? इसे पूर्ववत नहीं किया जा सकता।",
    "Clearing history removes stored transcripts from this machine. Stored facts above are kept until you forget them individually.": "इतिहास साफ़ करने से इस मशीन से सहेजे गए ट्रांसक्रिप्ट हट जाते हैं। ऊपर दिए सहेजे गए तथ्य तब तक रहते हैं जब तक आप उन्हें अलग-अलग भूल न दें।",
    "Clears stored transcripts and remembered facts from this machine. Settings and your API key are kept.": "इस मशीन से सहेजे गए ट्रांसक्रिप्ट और याद रखे गए तथ्य हटाता है। सेटिंग्स और आपकी API कुंजी बनी रहती हैं।",
    "Click Set and then press the key combination or mouse button you want.": "“सेट करें” पर क्लिक करें, फिर वह कुंजी संयोजन या माउस बटन दबाएँ जो आप चाहते हैं।",
    "Closest to how you speak.": "आपके बोलने के तरीके के सबसे नज़दीक।",
