    "Pages the assistant may fetch or summarise. Anything else is refused.": "वे पेज जिन्हें सहायक ला या सारांशित कर सकता है। बाकी सब अस्वीकार कर दिया जाता है।",
    "Phrases: {list}": "वाक्यांश: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "वह माइक्रोफ़ोन चुनें जिसमें आप वाकई बोलते हैं, फिर बोलते समय स्तर मीटर देखें। अच्छा इनपुट बिना क्लिपिंग के बार का लगभग दो-तिहाई तक पहुँचता है।",
    "Polish": "निखार",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "शॉर्टकट दबाएँ, स्वाभाविक बोलें, और आपके शब्द फ़ोकस वाले ऐप में पहुँचेंगे। यह तेज़ सेटअप आपके ऑडियो, शॉर्टकट और प्राथमिकताएँ ठीक कर देता है। सब कुछ बाद में सेटिंग्स में बदल सकते हैं।",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "“{name}” के लिए कुंजी संयोजन या माउस बटन दबाएँ। यहाँ प्रतीक्षा रोकने के लिए इस संवाद में Escape दबाएँ।",
    "Press the key combination or mouse button you want to use.": "वह कुंजी संयोजन या माउस बटन दबाएँ जिसे आप इस्तेमाल करना चाहते हैं।",
