    "Runs the same audio through the live and economy paths and shows how the transcripts differ, plus the real cost of each. It uses your microphone and is billable.": "उसी ऑडियो को लाइव और किफ़ायती दोनों रास्तों से गुज़ारता है और दिखाता है कि ट्रांसक्रिप्ट कैसे अलग हैं, साथ ही हर एक की असली लागत। आपके माइक्रोफ़ोन का उपयोग करता है और सशुल्क है।",
