    "The app rejected that setting change.": "ऐप ने वह सेटिंग बदलाव अस्वीकार कर दिया।",
    "The app starts minimised, with the wake listener off until it has finished loading.": "ऐप मिनिमाइज़ होकर शुरू होता है, लोड पूरा होने तक वेक श्रोता बंद रहता है।",
    "The assistant can only read and write inside these folders.": "सहायक केवल इन फ़ोल्डरों के भीतर पढ़ और लिख सकता है।",
    "The assistant can only touch what you approve here. Nothing is approved by default, so it will ask before reaching outside a folder you have added.": "सहायक केवल वही छू सकता है जिसे आप यहाँ स्वीकृत करें। डिफ़ॉल्ट रूप से कुछ भी स्वीकृत नहीं है, इसलिए आपके जोड़े फ़ोल्डर से बाहर जाने से पहले वह पूछेगा।",
    "The key is sent straight to the app and stored in Windows Credential Manager. It is never displayed again — only a short fingerprint is kept for confirmation.": "कुंजी सीधे ऐप को भेजी जाती है और Windows क्रेडेंशियल मैनेजर में रखी जाती है। यह दोबारा कभी नहीं दिखाई जाती — पुष्टि के लिए केवल एक छोटा फ़िंगरप्रिंट रखा जाता है।",
    "The voice the assistant speaks in. Dictation is unaffected.": "वह आवाज़ जिसमें सहायक बोलता है। श्रुतलेख पर कोई असर नहीं।",
