    ", and are pruned after the retention window set in Privacy. Nothing here is uploaded.": "، وتُحذف بعد مدة الاحتفاظ المحددة في «الخصوصية». لا يُرفع أي شيء من هذا.",
    "<b>These tests are billable.</b> Jarvis sends a short sample to the speech service and you are charged for it.": "<b>هذه الاختبارات مدفوعة.</b> يرسل Jarvis عيّنة قصيرة إلى خدمة الصوت وستُحتسب عليك تكلفتها.",
