    "Nothing is sent anywhere until you finish and start dictating, except the connection tests you choose to run.": "لا يُرسل أي شيء إلى أي مكان حتى تُنهي وتبدأ الإملاء، عدا اختبارات الاتصال التي تختار تشغيلها.",
    "Nothing matches “{query}”.": "لا شيء يطابق «{query}».",
    "Nothing remembered yet. Things you ask the assistant to remember will show up here.": "لم يُحفَظ شيء بعد. ما تطلب من المساعد تذكّره سيظهر هنا.",
    "Off by default. Sends crash reports and feature counters only — never transcripts or audio.": "معطّل افتراضيًا. يرسل تقارير الأعطال وعدّادات الميزات فقط — لا النصوص ولا الصوت أبدًا.",
    "Off by default. When on, the audio behind each transcript is written to disk so you can replay it.": "معطّل افتراضيًا. عند تشغيله، يُكتب صوت كل نص إلى القرص لتتمكن من إعادة تشغيله.",
    "OpenAI Codex CLI": "OpenAI Codex CLI",
    "Opt in — nothing runs until you press it.": "اختياري — لا يعمل شيء حتى تضغط.",
    "Optional accuracy comparison": "مقارنة دقة اختيارية",
    "Pages the assistant may fetch or summarise. Anything else is refused.": "الصفحات التي يجوز للمساعد جلبها أو تلخيصها. أي صفحة أخرى تُرفض.",
    "Phrases: {list}": "العبارات: {list}",
    "Pick the microphone you actually speak into, then watch the level meter while you talk. A good input peaks around two thirds of the bar without clipping.": "اختر الميكروفون الذي تتحدث فيه فعلًا، وراقب مقياس المستوى أثناء الكلام. الإدخال الجيد يبلغ نحو ثلثَي الشريط دون تشويش.",
    "Polish": "مصقول",
    "Press a shortcut, speak naturally, and your words land in whatever app has focus. This quick setup gets your audio, shortcuts, and preferences just right. You can change everything later in Settings.": "اضغط اختصارًا، وتحدّث بعفوية، وستصل كلماتك إلى التطبيق النشط. يضبط هذا الإعداد السريع الصوت والاختصارات والتفضيلات. يمكنك تغيير كل شيء لاحقًا في الإعدادات.",
    "Press the key combination or mouse button for “{name}”. Press Escape in this dialog to stop waiting here.": "اضغط تركيبة المفاتيح أو زر الفأرة من أجل «{name}». اضغط Escape في هذا الحوار للتوقف عن الانتظار هنا.",
    "Press the key combination or mouse button you want to use.": "اضغط تركيبة المفاتيح أو زر الفأرة الذي تريد استخدامه.",
