    "The assistant can only read and write inside these folders.": "لا يمكن للمساعد القراءة والكتابة إلا داخل هذه المجلدات.",
    "The assistant can only touch what you approve here. Nothing is approved by default, so it will ask before reaching outside a folder you have added.": "لا يلمس المساعد إلا ما تعتمده هنا. لا شيء معتمد افتراضيًا، لذا سيسأل قبل الخروج من مجلد أضفته.",
    "The key is sent straight to the app and stored in Windows Credential Manager. It is never displayed again — only a short fingerprint is kept for confirmation.": "يُرسل المفتاح مباشرة إلى التطبيق ويُخزَّن في «إدارة بيانات اعتماد Windows». لا يُعرض مجددًا — تُحفظ بصمة قصيرة فقط للتأكيد.",
