    "Theme set to {value}": "تم ضبط النمط على {value}",
    "These wake the app from anywhere in Windows. The defaults suit most people — change anything you like, and keep one hand free for the emergency stop.": "هذه تُنبّه التطبيق من أي مكان في Windows. القيم الافتراضية تناسب معظم الناس — غيّر ما تشاء وأبقِ يدًا حرة للإيقاف الطارئ.",
