    ", and are pruned after the retention window set in Privacy. Nothing here is uploaded.": ", ve Gizlilik’te belirlenen saklama süresinden sonra silinir. Bunların hiçbiri hiçbir yere yüklenmez.",
    "<b>These tests are billable.</b> Jarvis sends a short sample to the speech service and you are charged for it.": "<b>Bu testler ücretlidir.</b> Jarvis konuşma hizmetine kısa bir örnek gönderir ve bunun ücreti size yansıtılır.",
    "A more capable you.": "Daha yetenekli bir sen.",
    "A small local model listens for your wake phrase so you can start talking without touching the keyboard. Nothing is uploaded while it listens.": "Küçük bir yerel model, uyandırma ifadenizi dinler; böylece klavyeye dokunmadan konuşmaya başlayabilirsiniz. Dinlerken hiçbir şey yüklenmez.",
    "A smoother, faster way to work — with your voice.": "Daha akıcı ve hızlı bir çalışma biçimi — sesinizle.",
