    "Jarvis counts what it spends and stops when a cap is reached. Set a low cap for the first week and raise it once you know your habits.": "Jarvis ne harcadığını sayar ve bir üst sınıra ulaşınca durur. İlk hafta düşük bir sınır koyun, alışkanlıklarınızı öğrenince yükseltin.",
